def load_curves(cfg: StoreConfig) -> dict[str, Curve]:
    """Read every curve for cfg.asof. Fails loudly on a gap."""
    out: dict[str, Curve] = {}
    for ccy in cfg.currencies:
        raw = _fetch(cfg, f"curve/{ccy}/{cfg.asof:%Y%m%d}")
        if raw is None:
            raise MissingCurve(ccy, cfg.asof)
        out[ccy] = Curve.parse(raw)
    return out

def price(self, inst: Instrument, settle: date, mkt: MarketSnapshot) -> Priced:
    curve = self._curves[inst.currency]
    df = curve.discount(settle)
    if inst.kind is Kind.OPTION:
        vol = self._surface(inst.currency).vol(inst.strike, settle)
        pv = black76(inst, mkt.forward, vol, df)
    else:
        pv = df * inst.notional * (mkt.forward - inst.strike)
    return Priced(pv=pv, df=df, asof=mkt.asof)

