def build_instrument(spec: InstrumentSpec) -> Instrument:
    kind = Kind(spec.kind)
    cls = _REGISTRY.get(kind)
    if cls is None:
        raise UnknownInstrument(spec.kind)
    return cls.from_spec(spec)

def roll_forward(d: date, cal: Calendar) -> date:
    """Advance d to the next business day on cal."""
    if cal is None:
        raise CalendarMissing("no calendar bound to this request")
    moved = 0
    while not cal.is_business_day(d):
        d += timedelta(days=1)
        moved += 1
        if moved > MAX_ROLL_DAYS:
            raise RollOverflow(d, moved)
    return d

